import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"BiRefNet compile-parity probe — verdict","description":"","frontmatter":{"title":"BiRefNet compile-parity probe — verdict","type":"retro","date":"2026-10-14T00:00:00.000Z"},"headers":[],"relativePath":"graphopt/project/retros/birefnet-compile-parity.md","filePath":"vendored/graphopt/project/retros/birefnet-compile-parity.md"}`),a={name:`graphopt/project/retros/birefnet-compile-parity.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="birefnet-compile-parity-probe-—-verdict" tabindex="-1">BiRefNet compile-parity probe — verdict <a class="header-anchor" href="#birefnet-compile-parity-probe-—-verdict" aria-label="Permalink to “BiRefNet compile-parity probe — verdict”">​</a></h1><p>Question: the 34607e0 trial&#39;s delivered module timed 0.90× vs eager / 0.80× vs <code>torch.compile</code> on a reconstructed Swin stage under a FLOP-neutral extraction. Is the loss <em>lowering quality</em> (plan-tape interpreter overhead) rather than semantics — i.e. does <code>torch.compile(delivered)</code> recover <code>torch.compile(source)</code>?</p><p>Probe: <code>lab/probes/birefnet_parity_probe.py</code> (2026-10-14, main checkout, RTX 2050 4 GB, torch 2.14.0+cu130, <code>TORCHINDUCTOR_COMPILE_THREADS=2</code>).</p><p>Block: <strong>real timm <code>SwinTransformerBlock</code> ×2</strong> (timm 1.0.30), shaped like BiRefNet encoder stage 1 — dim 192, heads 6, window 7, alternating shift 0/3, input <code>(1, 56, 56, 192)</code> fp32, 892K params.</p><h2 id="arm-a-—-rules-none-flop-neutral-the-regime-under-test" tabindex="-1">Arm A — <code>--rules none</code> (FLOP-neutral; the regime under test) <a class="header-anchor" href="#arm-a-—-rules-none-flop-neutral-the-regime-under-test" aria-label="Permalink to “Arm A — --rules none (FLOP-neutral; the regime under test)”">​</a></h2><p>No rewrites; delivered = the source term re-lowered through the plan tape. <code>sink.verify</code> max_abs = <strong>0.0</strong> (bitwise identical — same ops, same order). Two runs:</p><table tabindex="0"><thead><tr><th>arm</th><th>run 1 µs</th><th>run 2 µs</th><th>peak MB</th></tr></thead><tbody><tr><td>source eager</td><td>5845.5</td><td>5837.8</td><td>107.4</td></tr><tr><td>source compile</td><td>4982.5</td><td>4961.8</td><td>109.7</td></tr><tr><td>delivered eager</td><td>5882.9</td><td>5881.1</td><td>174.1</td></tr><tr><td>delivered compile</td><td>5000.5</td><td>5007.8</td><td>109.7</td></tr></tbody></table><p>compiled(delivered) / compiled(source) = <strong>1.004× / 1.009× → PARITY</strong>. The tape overhead (~0.7% eager) is erased entirely by inductor; peak memory identical.</p><h2 id="arm-b-—-rules-default-the-composed-pipeline-set" tabindex="-1">Arm B — <code>--rules default</code> (the composed pipeline set) <a class="header-anchor" href="#arm-b-—-rules-default-the-composed-pipeline-set" aria-label="Permalink to “Arm B — --rules default (the composed pipeline set)”">​</a></h2><p>Only <code>sdpa_fold_add_drop</code> fires (timm&#39;s <em>manual</em> attention — q·kᵀ·scale + bias + softmax ·v — folds to <code>sdpa</code>; note real BiRefNet already calls <code>F.sdpa</code>, so this fold is reconstruction- specific). Extracted cost 0.406× of source; verify max_abs 9.5e-07.</p><table tabindex="0"><thead><tr><th>arm</th><th>µs</th><th>peak MB</th></tr></thead><tbody><tr><td>source eager</td><td>5824.3</td><td>107.4</td></tr><tr><td>source compile</td><td>4981.2</td><td>109.7</td></tr><tr><td>delivered eager</td><td>5455.3</td><td>154.2</td></tr><tr><td>delivered compile</td><td>4699.4</td><td>108.3</td></tr></tbody></table><p>compiled(delivered) / compiled(source) = <strong>0.943×</strong> — the delivered program is <em>faster</em> than compiled source: the FLOP win survives compilation.</p><h2 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to “Verdict”">​</a></h2><p><strong>Yes — compiling the delivered module recovers compiled parity.</strong> In the FLOP-neutral regime <code>compile(delivered) ≈ compile(source)</code> (1.00–1.01×, identical peak memory): the earlier 0.90×/0.80× loss was pure interpreter overhead, not lowering quality. With the standard rules the delivered module compiles to a <em>faster</em> program here (sdpa fold, 0.94×). Delivery via the tape is not a compiled- deployment tax — but eager deployments of a FLOP-neutral extraction still pay it (0.99×; worse in the 34607e0 trial&#39;s larger reconstruction, 0.90×).</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};